const fs = require('fs');
const data = fs.readFileSync(0, 'utf8');

let idx = 0;
function nextInt() {
  while (idx < data.length && data.charCodeAt(idx) <= 32) idx++;
  let num = 0;
  while (idx < data.length) {
    const c = data.charCodeAt(idx);
    if (c <= 32) break;
    num = num * 10 + (c - 48);
    idx++;
  }
  return num;
}

function solve() {
  const N = nextInt();
  const K = nextInt();

  const head = new Int32Array(N + 1).fill(-1);
  const E = 2 * (N - 1);
  const to = new Int32Array(E);
  const nxt = new Int32Array(E);

  let edge = 0;
  for (let i = 0; i < N - 1; i++) {
    const a = nextInt();
    const b = nextInt();

    to[edge] = b;
    nxt[edge] = head[a];
    head[a] = edge++;

    to[edge] = a;
    nxt[edge] = head[b];
    head[b] = edge++;
  }

  const parent = new Int32Array(N + 1);
  const order = new Int32Array(N);
  const stack = new Int32Array(N);

  let top = 0;
  stack[top++] = 1;
  parent[1] = 0;

  let orderLen = 0;
  while (top > 0) {
    const u = stack[--top];
    order[orderLen++] = u;

    for (let e = head[u]; e !== -1; e = nxt[e]) {
      const v = to[e];
      if (v === parent[u]) continue;
      parent[v] = u;
      stack[top++] = v;
    }
  }

  const INF = 1 << 30;
  const maxUnc = new Int32Array(N + 1);
  const minCen = new Int32Array(N + 1);

  function can(R) {
    let centers = 0;

    for (let i = N - 1; i >= 0; i--) {
      const u = order[i];

      let mx = 0;
      let mn = INF;

      for (let e = head[u]; e !== -1; e = nxt[e]) {
        const v = to[e];
        if (v === parent[u]) continue;

        const cmx = maxUnc[v];
        if (cmx >= 0) {
          const d = cmx + 1;
          if (d > mx) mx = d;
        }

        const cmn = minCen[v];
        if (cmn < INF) {
          const d = cmn + 1;
          if (d < mn) mn = d;
        }
      }

      if (mn < INF && mn + mx <= R) {
        mx = -1;
      }

      if (mx === R) {
        centers++;
        if (centers > K) return false;
        mn = 0;
        mx = -1;
      }

      maxUnc[u] = mx;
      minCen[u] = mn;
    }

    if (maxUnc[1] >= 0) centers++;
    return centers <= K;
  }

  let lo = 0;
  let hi = N;

  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (can(mid)) hi = mid;
    else lo = mid + 1;
  }

  console.log(lo);
}

solve();
